import "server-only";

import { createHmac, randomInt, timingSafeEqual } from "node:crypto";

import { SmsProviderError } from "./sms-provider";

/**
 * Application-owned OTP generation and verification primitives.
 *
 * The OTP is generated by the application (the SMS provider only
 * delivers it) and is NEVER stored or logged. What is persisted on the
 * challenge row is a keyed HMAC-SHA256 digest of the code, bound to the
 * organization, the challenge, and the phone number, so a digest cannot
 * be replayed across challenges or tenants and a database leak does not
 * reveal usable codes.
 *
 * The HMAC secret (MEMBER_OTP_HMAC_SECRET) is a server-only secret
 * independent of the Clerk secret and the SMS provider key. It is read
 * lazily — only when OTP functionality is exercised — so the rest of
 * the application does not depend on it at startup. A missing or short
 * secret fails closed with the normalized NOT_CONFIGURED error: no OTP
 * is ever sent when the application could not verify it later.
 */

/** Minimum secret material, in bytes, for the OTP HMAC key. */
export const OTP_HMAC_SECRET_MIN_BYTES = 32;

/** Shape of a stored digest: HMAC-SHA256 as lowercase hex. */
const OTP_HASH_HEX_PATTERN = /^[0-9a-f]{64}$/;

/**
 * Read and validate the OTP HMAC secret. Throws
 * SmsProviderError("NOT_CONFIGURED") when it is absent or carries less
 * than OTP_HMAC_SECRET_MIN_BYTES of material.
 */
export function readOtpHmacSecret(): string {
  const secret = process.env.MEMBER_OTP_HMAC_SECRET;
  if (!secret || Buffer.byteLength(secret, "utf8") < OTP_HMAC_SECRET_MIN_BYTES) {
    throw new SmsProviderError("NOT_CONFIGURED");
  }
  return secret;
}

/**
 * Generate a six-digit OTP using a cryptographically secure source,
 * zero-padded so leading-zero codes (e.g. "000007") occur naturally.
 * `nextInt` is injectable only so tests can pin the boundary values.
 */
export function generateOtpCode(
  nextInt: (exclusiveMax: number) => number = (exclusiveMax) =>
    randomInt(0, exclusiveMax),
): string {
  return nextInt(1_000_000).toString().padStart(6, "0");
}

/** The exact inputs a digest binds. Order and membership are the contract. */
export interface OtpDigestBinding {
  organizationId: string;
  challengeId: string;
  phoneNumber: string;
  otp: string;
}

function digestInput(binding: OtpDigestBinding): string {
  // Every component is colon-free by construction (UUIDs, digits), so
  // the joined form is unambiguous.
  return [
    "member-otp",
    binding.organizationId,
    binding.challengeId,
    binding.phoneNumber,
    binding.otp,
  ].join(":");
}

/**
 * Compute the stored digest for a challenge's OTP. Returns lowercase
 * hex (64 chars). The digest itself is never logged.
 */
export function computeOtpHash(
  secret: string,
  binding: OtpDigestBinding,
): string {
  return createHmac("sha256", secret)
    .update(digestInput(binding), "utf8")
    .digest("hex");
}

/**
 * Constant-time check of an entered OTP against the stored digest.
 * A missing or malformed stored digest simply does not match — the
 * caller surfaces the same generic verification failure as for a wrong
 * code.
 */
export function otpHashMatches(
  secret: string,
  binding: OtpDigestBinding,
  storedHash: string | null | undefined,
): boolean {
  if (!storedHash || !OTP_HASH_HEX_PATTERN.test(storedHash)) {
    return false;
  }
  const candidate = Buffer.from(computeOtpHash(secret, binding), "hex");
  const stored = Buffer.from(storedHash, "hex");
  if (candidate.length !== stored.length) {
    return false;
  }
  return timingSafeEqual(candidate, stored);
}
